// Fishing: zones, odds, rewards and the items generated from the roster.
// The roster itself (fishingRoster.ts) is generated by tools/fishing/build.py.

import type { Item } from '../types';
import { FISH, CATCH_OBJECTS, FISHING_GEAR } from './fishingRoster';

export type FishZone = 'C' | 'S' | 'D' | 'K' | 'F' | 'M';
export type FishRarity = 'common' | 'uncommon' | 'rare' | 'legendary';
export type FishBehaviour = 'darter' | 'steady' | 'sinker' | 'erratic';

export interface FishDef {
	id: string;
	name: string;
	image: string;
	zones: FishZone[];
	rarity: FishRarity;
	/** Fishing level needed (a better rod lets you reach a little above it). */
	level: number;
	time: 'any' | 'Dawnrise' | 'Duskfall';
	/** Empty = all year. */
	seasons: string[];
	behaviour: FishBehaviour;
	/** Length range in cm. */
	size: [number, number];
}

export interface CatchObjectDef {
	id: string;
	name: string;
	image: string;
	kind: 'junk' | 'treasure';
	weight: number;
}

export interface FishingGearDef {
	id: string;
	name: string;
	image: string;
	price: number;
	kind: 'rod' | 'bait';
	/** Rod tier (1-5) or bait effect ('fast' | 'rare'). */
	value: number | string;
}

export { FISH, CATCH_OBJECTS, FISHING_GEAR };

export const ZONE_NAMES: Record<FishZone, string> = {
	C: 'Coast',
	S: 'Open Sea',
	D: 'Deep Water',
	K: 'Cold Water',
	F: 'Freshwater',
	M: 'Swamp'
};

// Which fishing zone each map region's water belongs to.
export const REGION_ZONES: Record<string, FishZone> = {
	shallow_water: 'C',
	south_coast: 'C',
	pleasure_island: 'C',
	pleasure_island_waters: 'C',
	deserted_island: 'C',
	unknown_islands: 'C',
	north_beach: 'C',
	eastern_sea: 'S',
	northeastern_sea: 'S',
	southeastern_sea: 'S',
	western_sea: 'S',
	southern_sea: 'S',
	stormy_water: 'D',
	marjana_trench: 'D',
	cold_waters: 'K',
	icy_coast_south: 'K',
	glacier_top: 'K',
	glacier_bottom: 'K',
	ice_spring: 'K',
	ice_spring_island: 'K',
	waterfall: 'F',
	mountain_forest2: 'F',
	murky_water: 'M'
};

/** Where to fall back when nothing in a zone can bite yet (e.g. deep water at low level). */
export const ZONE_FALLBACK: Partial<Record<FishZone, FishZone>> = { D: 'S', M: 'F' };

export const RARITY_WEIGHT: Record<FishRarity, number> = { common: 60, uncommon: 28, rare: 10, legendary: 2 };
export const RARITY_XP: Record<FishRarity, number> = { common: 15, uncommon: 35, rare: 80, legendary: 250 };
export const OBJECT_XP = { junk: 5, treasure: 20 };
/** 0..1, drives the reel minigame. */
export const RARITY_DIFFICULTY: Record<FishRarity, number> = { common: 0.3, uncommon: 0.5, rare: 0.7, legendary: 0.9 };

export const GEM_IDS = ['ruby', 'sapphire', 'emerald', 'citrine', 'turquoise', 'amethyst'];

export const BOTTLE_MESSAGES = [
	'"To whoever finds this: the fish by the waterfall bite best at Dawnrise. You\'re welcome."',
	'"Day 40 on the island. Still no ship. Have befriended a crab. His name is Gerald."',
	'"If the Southern Sea Empire asks, I was never here, and neither were their pearls."',
	'"The tide took my boat, my boots and my dignity. Please return the boots."',
	'"Something enormous moves under the storm waters at Duskfall. I did not stay to see it."',
	'"Recipe for luck: one worm, one rod, and the patience of a heron."'
];

// ── Items ────────────────────────────────────────────────────────────────────

const ZONE_LIST = (zones: FishZone[]) => zones.map((z) => ZONE_NAMES[z]).join(', ');

export const fishingItems: Item[] = [
	...FISH.map(
		(f): Item => ({
			id: f.id,
			name: f.name,
			description: `A ${f.rarity} catch from the ${ZONE_LIST(f.zones).toLowerCase()}.`,
			image: f.image,
			type: 'general',
			flags: ['stackable', 'fish', f.rarity]
		})
	),
	...CATCH_OBJECTS.map(
		(o): Item => ({
			id: o.id,
			name: o.name,
			description: o.kind === 'treasure' ? 'Something valuable, fished out of the water.' : 'Fished out of the water. Not a fish.',
			image: o.image,
			type: 'general',
			flags: ['stackable', 'fish_catch', o.kind]
		})
	),
	...FISHING_GEAR.map(
		(g): Item => ({
			id: g.id,
			name: g.name,
			description:
				g.kind === 'rod'
					? `A tier ${g.value} rod. Bigger catch zone, rarer bites, and fish a little above your level.`
					: g.value === 'fast'
						? 'Used up on each cast. Fish bite sooner.'
						: 'Used up on each cast. Rare fish bite more often.',
			image: g.image,
			type: 'general',
			price: g.price || undefined,
			flags: g.kind === 'bait' ? ['stackable', 'grocery', 'bait'] : g.price ? ['grocery', 'fishing_rod'] : ['fishing_rod']
		})
	)
];

export const fishById: Record<string, FishDef> = Object.fromEntries(FISH.map((f) => [f.id, f]));
export const objectById: Record<string, CatchObjectDef> = Object.fromEntries(CATCH_OBJECTS.map((o) => [o.id, o]));
